document.addEventListener('DOMContentLoaded',()=>{const card=document.querySelector('.card');if(!card)return;let down=false,start=0;card.style.touchAction='pan-y';card.addEventListener('pointerdown',e=>{down=true;start=e.clientX;card.setPointerCapture(e.pointerId);card.style.transition='none'});card.addEventListener('pointermove',e=>{if(!down)return;const x=e.clientX-start;card.style.transform=`translateX(${x}px) rotate(${x/18}deg)`;card.style.boxShadow=`inset 0 0 0 999px ${x>0?'rgba(45,150,45,.12)':'rgba(224,83,83,.12)'}`});card.addEventListener('pointerup',e=>{if(!down)return;down=false;const x=e.clientX-start;card.style.transition='transform .3s ease,box-shadow .3s ease';if(Math.abs(x)>90){card.style.transform=`translateX(${x>0?500:-500}px) rotate(${x>0?20:-20}deg)`;setTimeout(()=>{if(x>0)document.querySelectorAll('.actions button')[2].click();else document.querySelectorAll('.actions button')[0].click();card.style.transform='';card.style.boxShadow=''},260)}else{card.style.transform='';card.style.boxShadow=''}})});
